using Botify.Domain.Models.Merchants.ValueObjects;

namespace Botify.Infrastructure.AiAgent
{
    public class ChatSession
    {
        // Unique identifier for the database record
        public Guid Id { get; set; }

        // Link the session to a specific merchant bot
        public Guid MerchantId { get; set; }

        // Telegram ID, WhatsApp Number, etc.
        public string ExternalChatId { get; set; }

        // The platform enum (Telegram, WhatsApp, etc.)
        public BotPlatform Platform { get; set; }

        // The "Fact List" generated by the Summarizer prompt
        public string? CurrentSummary { get; set; }

        // Counter to trigger re-summarization (e.g., every 10 messages)
        public int MessageCount { get; set; }

        // Timestamp to track when the user last spoke
        public DateTime LastInteractionAt { get; set; } = DateTime.UtcNow;

        // Factory method or constructor for clean creation
        public static ChatSession Create(Guid merchantId, string externalId, BotPlatform platform)
        {
            return new ChatSession
            {
                Id = Guid.NewGuid(),
                MerchantId = merchantId,
                ExternalChatId = externalId,
                Platform = platform,
                MessageCount = 0,
                LastInteractionAt = DateTime.UtcNow
            };
        }
    }
}